93	    /**
94	     * Connette utente ad applicazione
95	     */
96	    public function registerApp(AccessTokenInterface $data)
97	    {
98	
99	        // controllo id
100	        $userId = $this->id;
101	        if(!strlen($userId)) {
102	            throw new Exception("User not loaded, this should not happen!");
103	        }
104	
105	        // recupero valori
106	        $values = $data->getValues();
107	
108	        // controllo che lo stesso utente strava non sia già presente in database
109	        $checkExtUser =  self::where([["ext_id", $values["athlete"]["id"]], ["id", '<>', $userId] ])->get();
110	        if ($checkExtUser->count()) {
111	
112	            Log::channel('database')->info("utente strava già registrato: ".$userId."-".$values["athlete"]["id"], [
113	                "values" => $values
114	                ,"user-agent" => !empty($_SERVER["HTTP_USER_AGENT"]) ? $_SERVER["HTTP_USER_AGENT"] : ''
115	                ,"request" => !empty($_SERVER["REQUEST_URI"]) ? $_SERVER["REQUEST_URI"] : ''
116	            ]);
117	
118	            abort("400", "This Strava account is already registered.");
119	        }
120	
121	        // aggiorno
122	        $this->ext_id = $values["athlete"]["id"];
123	        $this->username = $values["athlete"]["username"];
124	        $this->resource_state = $values["athlete"]["resource_state"];
125	        $this->firstname = $values["athlete"]["firstname"];
126	        $this->lastname = $values["athlete"]["lastname"];
127	        $this->city = $values["athlete"]["city"];
128	        $this->state = $values["athlete"]["state"];
129	        $this->country = $values["athlete"]["country"];
130	        $this->sex = $values["athlete"]["sex"];
131	        // formato esempio 2014-02-05T22:31:47Z
132	        $this->ext_created_at = (new DateTime($values["athlete"]["created_at"]));
133	        $this->ext_updated_at = (new DateTime($values["athlete"]["updated_at"]));
134	        $this->badge_type_id = $values["athlete"]["badge_type_id"];
135	        $this->profile_medium = $values["athlete"]["profile_medium"];
136	        $this->profile = $values["athlete"]["profile"];
137	
138	        $this->token_expires_at = DateTime::createFromFormat('U', $data->getExpires());
139	        $this->token_expires_at_timestamp = $data->getExpires();
140	        $this->refresh_token = $data->getRefreshToken();
141	        $this->access_token = $data->getToken();
142	        $this->token_type = $values["token_type"];
143	
144	        $this->save();
145	
146	        return $this;
147	
148	    }
