12	
13	/**
14	 * Filtro periodo su base mensile ("mese da" / "mese a"), usato dalla pagina
15	 * Trend al posto di HasActivityPeriodFilter: i dati del grafico sono già
16	 * aggregati per mese, un DatePicker a livello di giorno sarebbe fuorviante.
17	 */
18	trait HasMonthlyPeriodFilter
19	{
20	    use HasFiltersForm {
21	        mountHasFilters as baseMountHasFilters;
22	    }
23	
24	    /**
25	     * Vedi il commento gemello in HasActivityPeriodFilter: sovrascriviamo
26	     * mountHasFilters (anziché un mount() separato) perché Livewire lo
27	     * invoca dopo mount(), quando $this->filters è già stato ripristinato
28	     * da sessione/URL.
29	     */
30	    public function mountHasFilters(): void
31	    {
32	        $this->baseMountHasFilters();
33	
34	        if (filled($this->filters['startDate'] ?? null) || filled($this->filters['endDate'] ?? null)) {
35	            return;
36	        }
37	
38	        $months = $this->getUserActivitiesMonthRange();
39	
40	        $this->filters['startDate'] = Carbon::createFromFormat('Y-m', $months->first())->startOfMonth()->toDateString();
41	        $this->filters['endDate'] = Carbon::createFromFormat('Y-m', $months->last())->endOfMonth()->toDateString();
42	
43	        $this->getFiltersForm()->fill($this->filters);
44	
45	        if ($this->persistsFiltersInSession()) {
46	            session()->put($this->getFiltersSessionKey(), $this->filters);
47	        }
48	    }
49	
50	    public function filtersForm(Form $form): Form
51	    {
52	        return $form
53	            ->schema([
54	                Select::make('preset')
55	                    ->label('Periodo rapido')
56	                    ->placeholder('Personalizzato')
57	                    ->options([
58	                        'current_year' => 'Anno corrente',
59	                        'last_year' => 'Ultimo anno',
60	                        'last_6_months' => 'Ultimi 6 mesi',
61	                    ])
62	                    ->live()
63	                    ->afterStateUpdated(function (?string $state, Set $set) {
64	                        if ($state === null) {
65	                            return;
66	                        }
67	
68	                        [$start, $end] = $this->getPresetRange($state);
69	
70	                        $set('startDate', $start);
71	                        $set('endDate', $end);
72	
73	                        // riportato a null subito dopo l'uso, altrimenti riselezionare
74	                        // lo stesso preset non genererebbe un cambio di stato
75	                        $set('preset', null);
76	                    })
77	                    ->columnSpanFull(),
78	
79	                Select::make('startDate')
80	                    ->label('Mese da')
81	                    ->options(fn () => $this->getMonthOptions(fn (Carbon $date) => $date->startOfMonth()))
82	                    ->native(false)
83	                    ->searchable()
84	                    // Choices.js tronca la lista renderizzata a optionsLimit (default 50):
85	                    // con più di 50 mesi di storico i più recenti sparivano dalla tendina.
86	                    ->optionsLimit($this->getUserActivitiesMonthRange()->count())
87	                    ->live(),
88	
89	                Select::make('endDate')
90	                    ->label('Mese a')
91	                    ->options(fn () => $this->getMonthOptions(fn (Carbon $date) => $date->endOfMonth()))
92	                    ->native(false)
93	                    ->searchable()
94	                    ->optionsLimit($this->getUserActivitiesMonthRange()->count())
95	                    ->live(),
96	            ])
97	            ->columns(2);
98	    }
99	
100	    /**
101	     * Estremi (mese da, mese a) di un preset rapido, agganciati al range di
102	     * mesi effettivamente disponibile: un valore fuori da quel range non
103	     * corrisponderebbe a nessuna opzione delle due Select.
104	     *
105	     * @return array{0: string, 1: string}
106	     */
107	    protected function getPresetRange(string $preset): array
108	    {
109	        $months = $this->getUserActivitiesMonthRange();
110	        $earliest = Carbon::createFromFormat('Y-m', $months->first())->startOfMonth();
111	        $latest = Carbon::createFromFormat('Y-m', $months->last())->endOfMonth();
112	
113	        $now = Carbon::now();
114	
115	        [$start, $end] = match ($preset) {
116	            'current_year' => [$now->copy()->startOfYear(), $now->copy()->endOfYear()],
117	            'last_year' => [$now->copy()->subMonthsNoOverflow(11)->startOfMonth(), $now->copy()->endOfMonth()],
118	            'last_6_months' => [$now->copy()->subMonthsNoOverflow(5)->startOfMonth(), $now->copy()->endOfMonth()],
119	        };
120	
121	        return [
122	            $start->max($earliest)->startOfMonth()->toDateString(),
123	            $end->min($latest)->endOfMonth()->toDateString(),
124	        ];
125	    }
126	
127	    /**
128	     * @param  callable(Carbon $date): Carbon  $boundary
129	     * @return array<string, string>
130	     */
131	    protected function getMonthOptions(callable $boundary): array
132	    {
133	        return $this->getUserActivitiesMonthRange()
134	            ->mapWithKeys(fn (string $month) => [
135	                $boundary(Carbon::createFromFormat('Y-m', $month))->toDateString() => ucfirst(
136	                    Carbon::createFromFormat('Y-m', $month)->locale('it')->translatedFormat('F Y')
137	                ),
138	            ])
139	            ->all();
140	    }
141	
142	    /**
143	     * Mesi (formato 'Y-m') fra la prima e l'ultima attività dell'utente.
144	     *
145	     * @return Collection<int, string>
146	     */
147	    protected function getUserActivitiesMonthRange(): Collection
148	    {
149	        return once(function () {
150	            $bounds = Activity::query()
151	                ->where('user_id', auth()->id())
152	                ->selectRaw('min(start_date_local) as min, max(start_date_local) as max')
153	                ->first();
154	
155	            $start = $bounds?->min ? Carbon::parse($bounds->min) : Carbon::now();
156	            $end = $bounds?->max ? Carbon::parse($bounds->max) : Carbon::now();
157	
158	            $months = collect();
159	            $cursor = $start->copy()->startOfMonth();
160	
161	            while ($cursor->lte($end)) {
162	                $months->push($cursor->format('Y-m'));
163	                $cursor->addMonth();
164	            }
165	
166	            return $months;
167	        });
168	    }
169	}
